'use strict';

/**
 * Public response headers for objects served from the runtime R2 bucket.
 *
 * These are EXACTLY the headers the static build (`_headers`, generated by
 * scripts/build-cloudflare-assets.js HEADERS_FILE_CONTENT) gives the same path today, so moving a
 * path from "static asset" to "runtime object" changes no customer-visible header: CORS
 * (cross-origin consumers of the feeds), caching, and the dossier Content-Security-Policy (without
 * it the Worker baseline would apply `default-src 'none'` and the page would render unstyled).
 *
 * SINGLE SOURCE OF TRUTH: `_headers` is canonical. A Worker cannot import the build script, so this
 * table is a copy, and tests-js/runtime-feed-headers.test.js evaluates the build's own rules and
 * FAILS if any value here differs. To change a header, change the build, then this file.
 */

// Headers every public path receives from the `/*` block.
const COMMON = Object.freeze({
  'Strict-Transport-Security': 'max-age=63072000; includeSubDomains; preload',
  'X-DNS-Prefetch-Control': 'on',
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
});

const LIVE_INTEL = Object.freeze({ ...COMMON,
  'Cache-Control': 'public, max-age=60, must-revalidate',
  'Access-Control-Allow-Origin': '*',
});

const API_LIVE = Object.freeze({ ...COMMON,
  'Content-Type': 'application/json; charset=UTF-8',
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, OPTIONS',
  'X-Powered-By': 'CYBERDUDEBIVASH SENTINEL APEX v4.0',
  'Cache-Control': 'public, max-age=60, must-revalidate',
});

const RSS = Object.freeze({ ...COMMON,
  'Content-Type': 'application/rss+xml; charset=UTF-8',
  'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400',
  'Access-Control-Allow-Origin': '*',
});

const DOSSIER = Object.freeze({ ...COMMON,
  'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  'Content-Security-Policy': 'default-src \'self\'; script-src \'self\' \'unsafe-inline\' https://cdnjs.cloudflare.com https://www.googletagmanager.com https://www.google-analytics.com https://checkout.razorpay.com; style-src \'self\' \'unsafe-inline\' https://fonts.googleapis.com; font-src \'self\' https://fonts.gstatic.com; img-src \'self\' data: https:; connect-src \'self\' https://blog.cyberdudebivash.in https://intel.cyberdudebivash.com https://www.google-analytics.com https://region1.google-analytics.com https://analytics.google.com https://stats.g.doubleclick.net https://api.rss2json.com https://api.allorigins.win https://corsproxy.io https://thingproxy.freeboard.io https://api.razorpay.com https://checkout.razorpay.com https://lumberjack.razorpay.com; frame-src \'self\' https://api.razorpay.com https://checkout.razorpay.com; frame-ancestors \'none\'',
});

module.exports = { COMMON, LIVE_INTEL, API_LIVE, RSS, DOSSIER };
